#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <libavcodec/avcodec.h>
#include <libavutil/channel_layout.h>
#include <libavutil/frame.h>
#include <libavutil/mem.h>
static void wavhdr(FILE *f,int rate,int ch,int n){uint32_t data=n*2,riff=36+data;uint16_t u;uint32_t d;fwrite("RIFF",1,4,f);d=riff;fwrite(&d,4,1,f);fwrite("WAVEfmt ",1,8,f);d=16;fwrite(&d,4,1,f);u=1;fwrite(&u,2,1,f);u=ch;fwrite(&u,2,1,f);d=rate;fwrite(&d,4,1,f);d=rate*ch*2;fwrite(&d,4,1,f);u=ch*2;fwrite(&u,2,1,f);u=16;fwrite(&u,2,1,f);fwrite("data",1,4,f);fwrite(&data,4,1,f);}
static void emit(FILE*f,AVFrame*fr,int ch){for(int i=0;i<fr->nb_samples;i++)for(int c=0;c<ch;c++){float v=0;switch(fr->format){case AV_SAMPLE_FMT_FLTP:v=((float*)fr->data[c])[i];break;case AV_SAMPLE_FMT_FLT:v=((float*)fr->data[0])[i*ch+c];break;case AV_SAMPLE_FMT_S16:v=((int16_t*)fr->data[0])[i*ch+c]/32768.0f;break;case AV_SAMPLE_FMT_S16P:v=((int16_t*)fr->data[c])[i]/32768.0f;break;default:break;}if(v>1)v=1;if(v<-1)v=-1;int16_t s=(int16_t)(v*32767);fwrite(&s,2,1,f);}}
int main(int argc,char**argv){if(argc<6){fprintf(stderr,"usage: codec ch in out extra [prepend]\n");return 1;}const char*name=argv[1];int ch=atoi(argv[2]);const char*inpath=argv[3];const char*out=argv[4];const char*extra=argv[5];int prepend=argc>6;const AVCodec*codec=avcodec_find_decoder_by_name(name);if(!codec){fprintf(stderr,"no codec\n");return 1;}AVCodecContext*ctx=avcodec_alloc_context3(codec);ctx->sample_rate=48000;av_channel_layout_default(&ctx->ch_layout,ch);int elen=strlen(extra);ctx->extradata=av_mallocz(elen+AV_INPUT_BUFFER_PADDING_SIZE);memcpy(ctx->extradata,extra,elen);ctx->extradata_size=elen;if(avcodec_open2(ctx,codec,NULL)<0){fprintf(stderr,"open fail\n");return 1;}FILE*in=fopen(inpath,"rb");FILE*o=fopen(out,"wb");fseek(o,44,SEEK_SET);long total=0;int frames=0,errors=0;uint32_t sz;while(fread(&sz,4,1,in)==1){unsigned char*buf=malloc(sz+(prepend?4:0));if(fread(buf+(prepend?4:0),1,sz,in)!=sz)break;if(prepend){uint32_t s=sz;memcpy(buf,&s,4);}AVPacket*p=av_packet_alloc();av_new_packet(p,sz+(prepend?4:0));memcpy(p->data,buf,sz+(prepend?4:0));free(buf);int r=avcodec_send_packet(ctx,p);av_packet_free(&p);if(r<0){errors++;continue;}AVFrame*fr=av_frame_alloc();while((r=avcodec_receive_frame(ctx,fr))==0){emit(o,fr,ch);total+=fr->nb_samples;frames++;av_frame_unref(fr);}av_frame_free(&fr);if(r!=AVERROR(EAGAIN)&&r!=AVERROR_EOF)errors++;}fseek(o,0,SEEK_SET);wavhdr(o,48000,ch,total);fclose(o);fclose(in);avcodec_free_context(&ctx);fprintf(stderr,"frames=%d samples=%ld errors=%d\n",frames,total,errors);return 0;}
